CREATE TABLE IF NOT EXISTS organizations (id UUID PRIMARY KEY, name TEXT NOT NULL, timezone TEXT NOT NULL DEFAULT 'Asia/Tehran', created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS users (id UUID PRIMARY KEY, organization_id TEXT NOT NULL, role TEXT NOT NULL CHECK(role IN ('MANAGER','INSPECTOR')), first_name TEXT NOT NULL, last_name TEXT NOT NULL, personnel_code TEXT, mobile TEXT, username TEXT NOT NULL UNIQUE, password_hash TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'ACTIVE' CHECK(status IN ('ACTIVE','SUSPENDED','PENDING')), created_at TEXT NOT NULL, updated_at TEXT NOT NULL, FOREIGN KEY(organization_id) REFERENCES organizations(id));
CREATE TABLE IF NOT EXISTS shops (id UUID PRIMARY KEY, organization_id TEXT NOT NULL, name TEXT NOT NULL, owner_name TEXT NOT NULL, mobile TEXT, national_id TEXT, business_license TEXT, category TEXT, address TEXT, latitude REAL NOT NULL, longitude REAL NOT NULL, accuracy REAL, location_timestamp TEXT, description TEXT, created_by TEXT NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, version INTEGER NOT NULL DEFAULT 1, FOREIGN KEY(organization_id) REFERENCES organizations(id), FOREIGN KEY(created_by) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS missions (id UUID PRIMARY KEY, organization_id TEXT NOT NULL, inspector_id TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('PENDING','ACTIVE','COMPLETED','CANCELLED')), start_time TEXT, end_time TEXT, start_latitude REAL, start_longitude REAL, end_latitude REAL, end_longitude REAL, distance REAL NOT NULL DEFAULT 0, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, version INTEGER NOT NULL DEFAULT 1, FOREIGN KEY(organization_id) REFERENCES organizations(id), FOREIGN KEY(inspector_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS track_points (id UUID PRIMARY KEY, mission_id TEXT NOT NULL, latitude REAL NOT NULL, longitude REAL NOT NULL, accuracy REAL, timestamp TEXT NOT NULL, seq INTEGER NOT NULL, FOREIGN KEY(mission_id) REFERENCES missions(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS inspections (id UUID PRIMARY KEY, organization_id TEXT NOT NULL, shop_id TEXT NOT NULL, inspector_id TEXT NOT NULL, mission_id TEXT NOT NULL, timestamp TEXT NOT NULL, result TEXT NOT NULL, notes TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, FOREIGN KEY(organization_id) REFERENCES organizations(id), FOREIGN KEY(shop_id) REFERENCES shops(id), FOREIGN KEY(inspector_id) REFERENCES users(id), FOREIGN KEY(mission_id) REFERENCES missions(id));
CREATE TABLE IF NOT EXISTS warnings (id UUID PRIMARY KEY, warning_number TEXT NOT NULL UNIQUE, organization_id TEXT NOT NULL, shop_id TEXT NOT NULL, inspector_id TEXT NOT NULL, mission_id TEXT NOT NULL, date TEXT NOT NULL, reason TEXT NOT NULL, description TEXT, status TEXT NOT NULL DEFAULT 'OPEN', created_at TEXT NOT NULL, updated_at TEXT NOT NULL, FOREIGN KEY(organization_id) REFERENCES organizations(id), FOREIGN KEY(shop_id) REFERENCES shops(id), FOREIGN KEY(inspector_id) REFERENCES users(id), FOREIGN KEY(mission_id) REFERENCES missions(id));
CREATE TABLE IF NOT EXISTS mission_events (id UUID PRIMARY KEY, mission_id TEXT NOT NULL, type TEXT NOT NULL, timestamp TEXT NOT NULL, latitude REAL, longitude REAL, metadata TEXT, FOREIGN KEY(mission_id) REFERENCES missions(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS audit_logs (id UUID PRIMARY KEY, organization_id TEXT NOT NULL, user_id TEXT, action TEXT NOT NULL, entity TEXT, entity_id TEXT, timestamp TEXT NOT NULL, metadata TEXT, FOREIGN KEY(organization_id) REFERENCES organizations(id));
CREATE TABLE IF NOT EXISTS sync_queue (id UUID PRIMARY KEY, user_id TEXT NOT NULL, entity_type TEXT NOT NULL, entity_id TEXT NOT NULL, operation TEXT NOT NULL, payload TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'pending', attempts INTEGER NOT NULL DEFAULT 0, last_error TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, UNIQUE(user_id,entity_type,entity_id,operation));
CREATE TABLE IF NOT EXISTS sessions (id UUID PRIMARY KEY, user_id TEXT NOT NULL, token_hash TEXT NOT NULL UNIQUE, expires_at TEXT NOT NULL, created_at TEXT NOT NULL, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS invites (id UUID PRIMARY KEY, organization_id TEXT NOT NULL, role TEXT NOT NULL CHECK(role='MANAGER'), token_hash TEXT NOT NULL UNIQUE, expires_at TEXT NOT NULL, used_at TEXT, created_at TEXT NOT NULL, FOREIGN KEY(organization_id) REFERENCES organizations(id));
CREATE INDEX IF NOT EXISTS idx_users_org ON users(organization_id);
CREATE INDEX IF NOT EXISTS idx_shops_org ON shops(organization_id);
CREATE INDEX IF NOT EXISTS idx_missions_org_status ON missions(organization_id,status);
CREATE INDEX IF NOT EXISTS idx_missions_inspector ON missions(inspector_id);
CREATE UNIQUE INDEX IF NOT EXISTS uq_missions_one_active_per_inspector ON missions(inspector_id) WHERE status='ACTIVE';
CREATE INDEX IF NOT EXISTS idx_track_mission_seq ON track_points(mission_id,seq);
CREATE INDEX IF NOT EXISTS idx_inspections_shop ON inspections(shop_id);
CREATE INDEX IF NOT EXISTS idx_warnings_shop ON warnings(shop_id);
CREATE INDEX IF NOT EXISTS idx_audit_org_time ON audit_logs(organization_id,timestamp);
